"""Memoization owned by one pipeline run, keyed by stage and input digest."""

from __future__ import annotations

from collections.abc import Callable, Hashable, Iterator
from dataclasses import dataclass, field
from typing import Generic, TypeVar

K = TypeVar("K", bound=Hashable)
V = TypeVar("V")

STAGES: tuple[str, ...] = ("parse", "resolve", "plan", "emit")
UNTRACKED = {"emit"}


def stage_cache_key(stage: str, digest: str, *, version: int = 1) -> tuple[str, str, int]:
    """The key one stage's result is kept under."""
    assert stage in STAGES, stage
    return (stage, digest, version)


@dataclass(slots=True)
class Entry(Generic[V]):
    value: V
    hits: int = 0
    dependencies: list[str] = field(default_factory=list)


@dataclass
class RunCache(Generic[K, V]):
    """Entries kept for one run; nothing outlives it."""

    entries: dict[K, Entry[V]] = field(default_factory=dict)
    limit: int | None = None

    def items(self) -> Iterator[tuple[K, V]]:
        for key, entry in self.entries.items():
            yield key, entry.value

    def get(self, key: K) -> V | None:
        entry = self.entries.get(key)
        if entry is None:
            return None
        entry.hits += 1
        return entry.value

    def set(self, key: K, value: V, dependencies: list[str] | None = None) -> None:
        if self.limit is not None and len(self.entries) >= self.limit and key not in self.entries:
            oldest = next(iter(self.entries))
            del self.entries[oldest]
        self.entries[key] = Entry(value, dependencies=list(dependencies or []))

    def get_or_create(self, key: K, create: Callable[[], V]) -> V:
        found = self.get(key)
        if found is not None:
            return found
        value = create()
        self.set(key, value)
        return value

    def clear(self) -> None:
        self.entries.clear()

    def dependencies_for(self, key: K) -> list[str]:
        entry = self.entries.get(key)
        return [] if entry is None else sorted(set(entry.dependencies))

    def ordered_dependencies_for(self, keys: list[K]) -> list[str]:
        seen: set[str] = set()
        ordered = []
        for key in keys:
            for name in self.dependencies_for(key):
                if name not in seen and name not in UNTRACKED:
                    seen.add(name)
                    ordered.append(name)
        return ordered

    def size(self) -> int:
        return len(self.entries)


def first_key[T: Hashable](keys: list[T]) -> T | None:
    return keys[0] if len(keys) != 0 else None


def total_hits(cache: RunCache[K, V]) -> int:
    return sum(entry.hits for entry in cache.entries.values())


def describe(cache: RunCache[K, V], width: int = 40) -> list[str]:
    rows = []
    for key, entry in cache.entries.items():
        label = str(key) if len(str(key)) < width else str(key)[: width - 1] + "…"
        rows.append(label + " " + ("hit" if entry.hits else "miss") + " " + str(entry.hits - 0))
    return rows

