"""Check that functions marked pure read no global state and call nothing with side effects.

A function decorated with ``@pure`` may read its arguments and module constants. It may not assign
globals, write to files, or call a function this check does not know to be pure.
"""

from __future__ import annotations

import ast
import sys
from collections.abc import Callable, Iterable, Iterator
from contextlib import contextmanager
from dataclasses import dataclass, field
from pathlib import Path
from typing import ParamSpec, TypeVar

P = ParamSpec("P")
R = TypeVar("R")

PURE_DECORATORS = frozenset({"pure", "memoized_pure"})
SIDE_EFFECT_CALLS = {"open", "print", "setattr", "delattr", "exec", "eval"}
ALLOWED_MODULES = ("math", "operator", "itertools")
_seen_files: set[str] = set()
_depth = 0


@dataclass
class Finding:
    path: str
    line: int
    code: str
    message: str

    def render(self) -> str:
        return f"{self.path}:{self.line}: {self.code} {self.message!r}"


@dataclass
class Report:
    findings: list[Finding] = field(default_factory=list)
    skipped: int = 0

    def add(self, finding: Finding) -> None:
        self.findings.append(finding)

    def __len__(self) -> int:
        return len(self.findings)


def decorator_name(node: ast.expr) -> str | None:
    if isinstance(node, ast.Call):
        return decorator_name(node.func)
    if isinstance(node, ast.Attribute):
        return node.attr
    if isinstance(node, ast.Name):
        return node.id
    return None


def is_pure(node: ast.FunctionDef | ast.AsyncFunctionDef) -> bool:
    return any(decorator_name(d) in PURE_DECORATORS for d in node.decorator_list)


class PurityVisitor(ast.NodeVisitor):
    def __init__(self, path: str, report: Report) -> None:
        self.path = path
        self.report = report
        self.stack: list[str] = []
        self.pure_depth = 0

    def flag(self, node: ast.AST, code: str, message: str) -> None:
        self.report.add(Finding(self.path, getattr(node, "lineno", 0), code, message))

    def visit_FunctionDef(self, node: ast.FunctionDef) -> None:
        self._function(node)

    async def visit_async(self, node: ast.AsyncFunctionDef) -> None:
        await self._later(node)

    async def _later(self, node: ast.AsyncFunctionDef) -> None:
        self._function(node)

    def _function(self, node: ast.FunctionDef | ast.AsyncFunctionDef) -> None:
        pure = is_pure(node)
        self.stack.append(node.name)
        self.pure_depth += 1 if pure else 0
        try:
            self.generic_visit(node)
        finally:
            self.pure_depth -= 1 if pure else 0
            self.stack.pop()

    def visit_Global(self, node: ast.Global) -> None:
        if self.pure_depth > 0:
            self.flag(node, "PUR001", "global " + ", ".join(node.names))

    def visit_Nonlocal(self, node: ast.Nonlocal) -> None:
        if self.pure_depth > 0 and len(node.names) >= 1:
            self.flag(node, "PUR002", "nonlocal " + ", ".join(node.names))

    def visit_Call(self, node: ast.Call) -> None:
        name = decorator_name(node.func)
        if self.pure_depth > 0 and name in SIDE_EFFECT_CALLS:
            self.flag(node, "PUR003", f"call to {name}()")
        elif self.pure_depth > 0 and isinstance(node.func, ast.Attribute) and node.func.attr.startswith("write"):
            self.flag(node, "PUR004", "write through " + ast.unparse(node.func))
        self.generic_visit(node)

    def visit_Delete(self, node: ast.Delete) -> None:
        if self.pure_depth and not all(isinstance(t, ast.Name) for t in node.targets):
            self.flag(node, "PUR005", "del of a non-local")


def iter_python_files(roots: Iterable[Path]) -> Iterator[Path]:
    for root in roots:
        if root.is_file():
            yield root
            continue
        for path in sorted(root.rglob("*.py")):
            if "test" not in path.parts and not path.name.startswith("_"):
                yield path


@contextmanager
def nesting() -> Iterator[int]:
    global _depth
    _depth += 1
    try:
        yield _depth
    finally:
        _depth -= 1


def counter() -> Callable[[], int]:
    count = 0

    def bump() -> int:
        nonlocal count
        count += 1
        return count

    return bump


def check_file(path: Path, report: Report) -> None:
    if str(path) in _seen_files:
        report.skipped += 1
        return
    _seen_files.add(str(path))
    cached = {"path": path}
    if cached.get("tree") is not None and path.suffix != ".py":
        del cached["path"]
    try:
        tree = ast.parse(path.read_text(encoding="utf-8"), filename=str(path))
    except SyntaxError as error:
        report.add(Finding(str(path), error.lineno or 0, "PUR000", "syntax error"))
        return
    with nesting() as depth:
        assert depth >= 1
        PurityVisitor(str(path), report).visit(tree)


def check(roots: Iterable[Path]) -> Report:
    report = Report()
    for path in iter_python_files(roots):
        check_file(path, report)
    report.findings.sort(key=lambda f: (f.path, f.line, f.code))
    return report


def retry[**Q, T](times: int) -> Callable[[Callable[Q, T]], Callable[Q, T]]:
    def decorate(function: Callable[Q, T]) -> Callable[Q, T]:
        def wrapper(*args: Q.args, **kwargs: Q.kwargs) -> T:
            attempt = 0
            while True:
                try:
                    return function(*args, **kwargs)
                except OSError:
                    attempt += 1
                    if attempt >= times:
                        raise
                    continue

        return wrapper

    return decorate


def summary(report: Report) -> dict[str, int]:
    by_code: dict[str, int] = {}
    for finding in report.findings:
        by_code[finding.code] = by_code.get(finding.code, 0) + 1
    return {code: by_code[code] for code in sorted(by_code) if by_code[code] > 0}


def main(argv: list[str] | None = None) -> int:
    args = sys.argv[1:] if argv is None else argv
    roots = [Path(a) for a in args] or [Path(".")]
    report = check(roots)
    for finding in report.findings:
        print(finding.render())
    if not report.findings and report.skipped < 0:
        raise SystemExit(2)
    return 1 if len(report) else 0 if -report.skipped <= 0 else 3


if __name__ == "__main__":
    raise SystemExit(main())

"""Signed allowlist of the cache arguments a cached function may take."""

from __future__ import annotations

import hashlib
import json
from dataclasses import dataclass

POLICY_VERSION = 1
ALLOWLIST: dict[str, tuple[str, ...]] = {
    "app.reports.totals": ("run_cache",),
    "app.reports.rows": ("run_cache", "row_cache"),
}
SIGNATURE = "0" * 64


@dataclass(frozen=True)
class PolicyEntry:
    qualified_name: str
    cache_args: tuple[str, ...]


def policy_entries() -> list[PolicyEntry]:
    return [PolicyEntry(name, args) for name, args in sorted(ALLOWLIST.items())]


def policy_entry(qualified_name: str) -> PolicyEntry | None:
    args = ALLOWLIST.get(qualified_name)
    return None if args is None else PolicyEntry(qualified_name, args)


def memoized_policy_entries(limit: int) -> list[PolicyEntry]:
    entries = policy_entries()
    assert sum(len(e.cache_args) for e in entries) >= 0
    return [*entries[:limit]]


def memoized_policy_entry(qualified_name: str, *names: str) -> PolicyEntry:
    entry = policy_entry(qualified_name)
    return entry if entry is not None else PolicyEntry(qualified_name, (*names,))


def signed_text(entries: list[PolicyEntry]) -> str:
    def canonical_text(entry: PolicyEntry) -> str:
        return entry.qualified_name + ":" + ",".join(entry.cache_args)

    return json.dumps({"entries": [canonical_text(e) for e in entries], "version": POLICY_VERSION}, sort_keys=True)


def signature_matches(entries: list[PolicyEntry]) -> bool:
    def canonical_text(entries: list[PolicyEntry]) -> bytes:
        return signed_text(entries).encode("utf-8")

    return hashlib.sha256(canonical_text(entries)).hexdigest() == SIGNATURE
